public void executeQuery()
{
    if(!leavePlan)
    {
        leavePlan = this.formRun().args().record() as LeavePlan;
    }

    if(leavePlan.NVHcmLeaveGroupId != "")
    {
        Query query = this.query();
        QueryBuildDataSource workerDS = query.dataSourceTable(tableNum(HcmWorker));
        workerDS.addRange(fieldNum(HcmWorker, NVHcmLeaveGroupId)).value(leavePlan.NVHcmLeaveGroupId);
    }
    next executeQuery();
}
